/**
 * One IndexedDB database the window, the DB worker and the SW may each hold open (story 387,
 * consistency-04). Pure — no window or DOM — so every realm imports it.
 *
 * - A rejected open is not kept: the next call opens again, instead of every call
 *   rejecting until the page or worker dies.
 * - A connection closes on `versionchange`, so an upgrade or a /debug delete is not
 *   blocked by it; the next call reopens.
 */
export interface IdbStore {
    db(): Promise<IDBDatabase>;
    /** Close the cached connection and forget it (tests swap the `indexedDB` global). */
    reset(): void;
}

export function openIdbStore(options: {
    name: string;
    version: number;
    upgrade: (db: IDBDatabase) => void;
}): IdbStore {
    let dbPromise: Promise<IDBDatabase> | null = null;

    function open(): Promise<IDBDatabase> {
        return new Promise((resolve, reject) => {
            const req = indexedDB.open(options.name, options.version);
            req.onupgradeneeded = () => options.upgrade(req.result);
            req.onsuccess = () => {
                const db = req.result;
                db.onversionchange = () => {
                    db.close();
                    dbPromise = null;
                };
                resolve(db);
            };
            req.onerror = () => reject(req.error ?? new Error(`Failed to open IndexedDB ${options.name}`));
        });
    }

    return {
        db() {
            dbPromise ??= open().catch((error: unknown) => {
                dbPromise = null;
                throw error;
            });
            return dbPromise;
        },
        reset() {
            if (dbPromise) void dbPromise.then((db) => db.close()).catch(() => undefined);
            dbPromise = null;
        },
    };
}

export function awaitTx(tx: IDBTransaction): Promise<void> {
    return new Promise((resolve, reject) => {
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error ?? new Error('IndexedDB transaction failed'));
        tx.onabort = () => reject(tx.error ?? new Error('IndexedDB transaction aborted'));
    });
}

/** jsdom's older Blob has no arrayBuffer(); real browsers do. */
export async function blobToArrayBuffer(blob: Blob): Promise<ArrayBuffer> {
    if (typeof (blob as Blob & { arrayBuffer?: unknown }).arrayBuffer === 'function') {
        return blob.arrayBuffer();
    }
    return new Promise<ArrayBuffer>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            if (reader.result instanceof ArrayBuffer) resolve(reader.result);
            else reject(new Error('FileReader did not return ArrayBuffer'));
        };
        reader.onerror = () => reject(reader.error ?? new Error('Failed to read blob'));
        reader.readAsArrayBuffer(blob);
    });
}
